namespace sarif.handlers.result.sample;




using com.contrastsecurity.sarif;

using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.handlers;
using sarif.view;

public class SarifReturnTypeResultHandler : SarifResultHandler {

	/* @Override */
	public string getKey() {
		return "return type";
	}

	/* @Override */
	public string parse() {
		ToolComponent tc = df.getComponentMap().get(getKey());
		ReportingDescriptorReference @ref = df.getTaxa().get(getKey());
		if (tc != null) {
			List<ReportingDescriptor> view = new(tc.getTaxa());
			if (@ref != null) {
				int index = @ref.getIndex().intValue();
				if (index < view.size()) {
					return view.get(index).getId();
				}
			}
		}
		return null;
	}

	/* @Override */
	public string getActionName() {
		return "Commit";
	}

	/* @Override */
	public ProgramTask getTask(SarifResultsTableProvider tableProvider) {
		return new ReturnTypeTaxonomyTask(tableProvider);
	}

	private class ReturnTypeTaxonomyTask : ProgramTask {

		private SarifResultsTableProvider tableProvider;

		protected ReturnTypeTaxonomyTask(SarifResultsTableProvider provider) : base(provider.getController().getProgram(), "ReturnTypeTaxonomyTask", true, true,
				true)
    {
			this.tableProvider = provider;
		}

		/* @Override */
		protected void doRun(TaskMonitor monitor) {
			int col = tableProvider.getIndex("return type");
			int[] selected = tableProvider.filterTable.getTable().getSelectedRows();
			foreach (int row in selected) {
				Function func = tableProvider.getController()
						.getProgram()
						.getFunctionManager()
						.getFunctionContaining(tableProvider.model.getAddress(row));
				string value = (string) tableProvider.getValue(row, col);
				setReturnType(func, value);
			}
		}

		private bool setReturnType(Function func, string type) {
			if (type != null) {
				try {
					func.setReturnType(parseDataType(type), func.getSignatureSource());
					return true;
				}
				catch (InvalidInputException e) {
					throw new RuntimeException("Error setting return type for " + func);
				}
			}
			return false;
		}

		private DataType parseDataType(string datatype) {
			switch (datatype) {
				case "int":
					return new IntegerDataType();
				case "uint":
				case "__ssize_t":
					return new UnsignedIntegerDataType();
				case "bool":
					return new BooleanDataType();
				case "char":
					return new CharDataType();
				case "char *":
				case "FILE *":
				case "void *":
				case "whcar_t *":
				case "tm *":
					return new PointerDataType();
				case "void":
					return new VoidDataType();
				case "double":
					return new DoubleDataType();
				case "long":
					return new LongDataType();
				case "longdouble":
					return new LongDoubleDataType();
				case "ulong":
					return new UnsignedLongDataType();
			}
			return null;
		}

	}
}
